/**
 * Unit tests for the UserAcceptedTermnsOfUseAcceptDateAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserAcceptedTermnsOfUseAcceptDateAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAcceptDate returns null on a freshly created holder.
     */
    public function testAcceptDateNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseAcceptDateAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAcceptDateAssigned());
        $this->assertNull($holder->getAcceptDate());
    }
}
class ImplWithUserAcceptedTermnsOfUseAcceptDateAttributeHolderUnitTest
